static int loop_resolve(const char *path, struct vfs_ref *ref)
{
    struct vfs_ref first;
    struct vfs_mount *mnt;
    int rc;

    rc = vfs_resolve(0, path, 0, &first, 0, 0);
    if (rc != 0) {
        return rc;
    }
    mnt = first.mnt;
    vfs_ns_lock(mnt);
    rc = vfs_resolve(0, path, 0, ref, 0, 0);
    if (rc == 0 && ref->mnt != mnt) {
        vfs_ref_release(ref);
        rc = -EBUSY;
    }
    if (rc != 0) {
        vfs_ns_unlock(mnt);
    }
    vfs_ref_release(&first);
    return rc;
}

