static int loop_resolve(const char *path, struct vfs_ref *ref)
{
    int rc = vfs_resolve(0, path, 0, ref, 0, 0);

    if (rc == 0) {
        vfs_ns_lock(ref->mnt);
    }
    return rc;
}
